INSERT INTO products (product_id, name, official_name, item_type, size, sku, upc, description, dimensions, is_online_exclusive, mfr_date, mfr_price, season) VALUES (34, 'Christmas Past', 'Yes', 'Illuma-Lid Topper', 'Large', 1208826, NULL, 'Special seasonally-themed jar topper helps candles burn cleaner and more evenly! This is an accent that is practical as well as decorative. Made exclusively for Yankee Candle, this Illuma-Lid® jar topper is specifically designed to reduce the effects of drafts. Simply place the lid on a jar candle and it will help the candle flame burn steadier while allowing superb distribution of the scent. Designed to fit our large and medium jar candles.', NULL, 1, NULL, NULL, 'Christmas');
