INSERT INTO products (product_id, name, official_name, item_type, size, sku, upc, description, dimensions, is_online_exclusive, mfr_date, mfr_price, season) VALUES (57, 'Enchanted Tree', 'Yes', 'Jar Candle Tray (3D)', 'Large', 2656590, NULL, 'Bring home woodland charm. Wandering brass vines and fall leaves add a rustic yet elegant touch to your space. It''s fun to prepare your home for every season, any celebration or just because. We love how candle holders make any setting special and how they complement our fragrances. Try a new candle holder and see what a big change a little touch can make! For use with our Original Large Jar Candles, Large Tumbler Candles, and 3-Wick Candles.', '6.69" L x 6.69" W x 4.72" H', 0, '2025-10-09', 19.99, 'Year-Round');
INSERT INTO products (product_id, name, official_name, item_type, size, sku, upc, description, dimensions, is_online_exclusive, mfr_date, mfr_price, season) VALUES (58, 'Fall Gourds', 'Yes', 'Jar Candle Holder', 'Large', 2656551, NULL, 'Fall leaves dance around a pile of pumpkins and gourds fresh from a fall harvest — blue, orange, and green pumpkins will add a pop of color to your décor with this crackle glass Jar Candle Holder. It''s fun to prepare your home for every season, any celebration or just because. We love how candle holders make any setting special and how they complement our fragrances. Try a new candle holder and see what a big change a little touch can make! For use with our Original Large Jar Candles and Large Tumbler Candles.', '4.7" L x 4.7" W x 6.8" H', 0, '2026-01-28', 29.99, 'Fall');
INSERT INTO products (product_id, name, official_name, item_type, size, sku, upc, description, dimensions, is_online_exclusive, mfr_date, mfr_price, season) VALUES (59, 'Fall Leaves', 'Yes', 'Jar Candle Holder', 'Large', 2656549, NULL, 'Bring home the feeling of wind in your hair as the red and orange fallen leaves of autumn surround you — made with a wooden-base finish and metal leaf accents. It''s fun to prepare your home for every season, any celebration or just because. We love how candle holders make any setting special and how they complement our fragrances. Try a new candle holder and see what a big change a little touch can make! For use with our Original Large Jar Candles and Large Tumbler Candles.', '4.1" L x 4.1" W x 4.49" H', 0, '2025-10-09', 14.99, 'Fall');
